<script setup>import {Head,Link} from '@inertiajs/vue3';import AppLayout from '../Layouts/AppLayout.vue';import EmptyState from '../Components/EmptyState.vue';defineProps({standings:Array,awards:Array});</script><template><Head title="Insights"/><AppLayout><div class="flex flex-wrap items-end justify-between gap-4"><div><p class="label">Numbers & receipts</p><h1 class="mt-2 text-4xl font-black">League intelligence.</h1><p class="mt-2 text-[#718078]">Form, discipline and the moments that define the season.</p></div><Link href="/hall-of-fame" class="btn-primary">Open Hall of Fame →</Link></div><template v-if="standings.length"><div class="mt-8 grid gap-5 lg:grid-cols-3"><section class="card p-6 lg:col-span-2"><h2 class="text-xl font-black">Gameweek form</h2><div class="mt-7 space-y-5"><div v-for="r in standings" :key="r.id"><div class="mb-2 flex justify-between text-sm"><b>{{r.entry.manager_name}}</b><span>{{r.points}} pts</span></div><div class="h-2 overflow-hidden rounded-full bg-[#e7ebe7] dark:bg-[#20332a]"><div class="h-full rounded-full bg-[#1d7650]" :style="{width:`${Math.min(100,r.points/Math.max(1,...standings.map(x=>x.points))*100)}%`}"></div></div></div></div></section><section class="card p-6"><h2 class="text-xl font-black">Discipline</h2><div class="mt-6 space-y-5"><div><span class="label">Most patient</span><p class="mt-1 text-lg font-black">{{[...standings].sort((a,b)=>a.transfers-b.transfers)[0].entry.manager_name}}</p></div><div><span class="label">Bench pain</span><p class="mt-1 text-lg font-black">{{[...standings].sort((a,b)=>b.bench_points-a.bench_points)[0].entry.manager_name}}</p></div><div><span class="label">League pace</span><p class="mt-1 text-lg font-black">{{Math.round(standings.reduce((a,x)=>a+x.total_points,0)/standings.length)}} avg</p></div></div></section></div><section class="mt-7"><h2 class="mb-4 text-xl font-black">Honours board</h2><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><Link v-for="a in awards" :href="`/awards/${a.id}/card`" class="card p-5"><span class="label">{{a.title}}</span><p class="mt-2 font-bold">{{a.description}}</p><small class="mt-3 block text-[#1d6949]">Share →</small></Link></div></section></template><EmptyState v-else class="mt-8" title="Insights need match data" text="Ownership, differentials, captaincy and award history will appear as snapshots are collected."/></AppLayout></template>
